#!/usr/bin/env python3
import base64, hmac, hashlib, json, sys, time, urllib.request, urllib.parse

BASE = "http://locktalk:1337"

def b64u(b): return base64.urlsafe_b64encode(b).rstrip(b'=').decode()
def dec(s):
    s += '=' * (-len(s) % 4)
    return base64.urlsafe_b64decode(s.encode())
def dec_jwt(t):
    parts = t.split('.')
    out = {}
    for name, i in (('header',0),('payload',1)):
        try: out[name] = json.loads(dec(parts[i]))
        except Exception as e: out[name] = 'ERR:%s' % e
    return out

def make(header, payload, key=b'', hashname='sha256'):
    h = b64u(json.dumps(header, separators=(',',':')).encode())
    p = b64u(json.dumps(payload, separators=(',',':')).encode())
    msg = (h+'.'+p).encode()
    if str(header.get('alg','')).lower() == 'none':
        sig = b''
    else:
        sig = hmac.new(key if isinstance(key,bytes) else key.encode(), msg, getattr(hashlib, hashname)).digest()
    return h+'.'+p+'.'+b64u(sig)

def req(path, headers=None, method='GET', data=None):
    url = BASE + path
    r = urllib.request.Request(url, data=data, method=method, headers=headers or {})
    try:
        with urllib.request.urlopen(r, timeout=10) as resp:
            return resp.status, dict(resp.headers), resp.read().decode('utf-8','replace')
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers), e.read().decode('utf-8','replace')
    except Exception as e:
        return -1, {}, repr(e)

