{"content": "#!/usr/bin/env python3
"""PS256 JWT signer using cryptography, plus JWKS from local priv.pem."""
import base64, json, sys
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import padding, rsa

def b64u(b): return base64.urlsafe_b64encode(b).rstrip(b'=').decode()

def load_key(path='/workspace/loot/priv.pem'):
    with open(path,'rb') as f:
        return serialization.load_pem_private_key(f.read(), password=None)

def pub_jwk(key=None):
    key = key or load_key()
    pub = key.public_key().public_numbers()
    n = pub.n.to_bytes((pub.n.bit_length()+7)//8, 'big')
    e = pub.e.to_bytes((pub.e.bit_length()+7)//8, 'big')
    return {'kty':'RSA','n':b64u(n),'e':b64u(e),'alg':'PS256','use':'sig'}

def sign_ps256(header, payload, key=None):
    key = key or load_key()
    h = b64u(json.dumps(header, separators=(',',':')).encode())
    p = b64u(json.dumps(payload, separators=(',',':')).encode())
    msg = (h+'.'+p).encode()
    sig = key.sign(msg, padding.PSS(mgf=padding.MGF1(hashes.SHA256()), salt_length=32), hashes.SHA256())
    return h+'.'+p+'.'+b64u(sig)

if __name__ == '__main__':
    print(pub_jwk())
